#include <cassert>
#include <cstdint>
#include "../include/FlameMonitor.h"
static FlameInput sample(uint32_t now,bool f1v=true,bool f1=false,bool f2v=true,bool f2=false,bool gv=true,bool gas=false){FlameInput i={};i.nowMs=now;i.f1Valid=f1v;i.f1Detected=f1;i.f2Valid=f2v;i.f2Detected=f2;i.burnerGasValid=gv;i.burnerGasOn=gas;return i;}
static FlameMonitor make(){FlameTiming t={300,300,500,300,100,500};return FlameMonitor(t);}
static bool event(const FlameOutput&o,FlameCause c,bool active){for(uint8_t i=0;i<o.eventCount;i++)if(o.events[i].cause==c&&o.events[i].active==active)return true;return false;}
static void f1DebounceClear(){FlameMonitor m=make();assert(!m.update(sample(0,true,true)).f1Alarm);assert(!m.update(sample(299,true,true)).f1Alarm);FlameOutput a=m.update(sample(300,true,true));assert(a.f1Alarm&&event(a,FlameCause::F1_FIRE,true));assert(m.update(sample(400,true,false)).f1Alarm);assert(m.update(sample(700,true,false)).f1Alarm==false);}
static void f1InputFaultOpensAndCloses(){FlameMonitor m=make();FlameOutput bad=m.update(sample(0,false));assert(bad.faultActive&&event(bad,FlameCause::F1_SENSOR_FAULT,true));FlameOutput recovered=m.update(sample(100,true,false));assert(!recovered.faultActive&&event(recovered,FlameCause::F1_SENSOR_FAULT,false));}
static void f2FaultTracksValidityWhileGasOff(){FlameMonitor m=make();FlameOutput bad=m.update(sample(0,true,false,false,false,true,false));assert(bad.faultActive&&event(bad,FlameCause::F2_SENSOR_FAULT,true));FlameOutput stillBad=m.update(sample(100,true,false,false,false,true,false));assert(stillBad.faultActive&&!event(stillBad,FlameCause::F2_SENSOR_FAULT,false));FlameOutput recovered=m.update(sample(200,true,false,true,false,true,false));assert(!recovered.faultActive&&event(recovered,FlameCause::F2_SENSOR_FAULT,false));}
static void startupUsesOwnTimeout(){FlameTiming t={300,300,1000,300,100,400};FlameMonitor m(t);m.update(sample(0,true,false,true,false,true,true));FlameOutput before=m.update(sample(399,true,false,true,false,true,true));assert(!event(before,FlameCause::F2_STARTUP_UNCONFIRMED,true));FlameOutput timeout=m.update(sample(400,true,false,true,false,true,true));assert(event(timeout,FlameCause::F2_STARTUP_UNCONFIRMED,true));}
static void ignition(){FlameMonitor m=make();m.update(sample(0));m.update(sample(1,true,false,true,false,true,true));assert(m.update(sample(200,true,false,true,true,true,true)).f2State==F2State::IGNITION_WAIT);assert(m.update(sample(301,true,false,true,true,true,true)).f2State==F2State::LIT);FlameMonitor f=make();f.update(sample(0));f.update(sample(1,true,false,true,false,true,true));FlameOutput o=f.update(sample(501,true,false,true,false,true,true));assert(o.f2Alarm&&event(o,FlameCause::F2_IGNITION_TIMEOUT,true));}
static void lossAndOff(){FlameMonitor m=make();m.update(sample(0));m.update(sample(1,true,false,true,true,true,true));m.update(sample(301,true,false,true,true,true,true));m.update(sample(302,true,false,true,false,true,true));assert(!m.update(sample(500,true,false,true,true,true,true)).f2Alarm);m.update(sample(600,true,false,true,false,true,true));FlameOutput o=m.update(sample(900,true,false,true,false,true,true));assert(o.f2Alarm&&event(o,FlameCause::F2_FLAME_LOST,true));FlameOutput off=m.update(sample(901,true,false,true,false,true,false));assert(!off.f2Alarm&&event(off,FlameCause::F2_FLAME_LOST,false));}
static void startupFaultAndWrap(){FlameMonitor m=make();m.update(sample(0,true,false,true,false,true,true));FlameOutput s=m.update(sample(500,true,false,true,false,true,true));assert(s.f2Alarm&&event(s,FlameCause::F2_STARTUP_UNCONFIRMED,true));FlameMonitor bad=make();FlameOutput e=bad.update(sample(0,true,false,false,false,true,true));assert(e.f2Alarm&&e.faultActive&&event(e,FlameCause::F2_SENSOR_FAULT,true));FlameOutput recovered=bad.update(sample(1,true,false,true,true,true,true));assert(recovered.f2State==F2State::STARTUP_WAIT);FlameMonitor unknownGas=make();FlameOutput g=unknownGas.update(sample(0,true,false,true,false,false,false));assert(g.faultActive);FlameMonitor w=make();uint32_t t=0xFFFFFF00u;w.update(sample(t));w.update(sample(t+1,true,false,true,false,true,true));assert(event(w.update(sample(t+501,true,false,true,false,true,true)),FlameCause::F2_IGNITION_TIMEOUT,true));}
int main(){f1DebounceClear();f1InputFaultOpensAndCloses();f2FaultTracksValidityWhileGasOff();startupUsesOwnTimeout();ignition();lossAndOff();startupFaultAndWrap();}
